/** Manual override ΓÇö set a card's counters to an exact value. */
const setCount = useCallback((instanceId: string, count: number) => {
  setTracker((prev) => {
    let log = prev.game.log;
    const cards = prev.game.cards.map((c) => {
      if (c.instanceId !== instanceId) return c;
      const to = clampCount(count, c.direction, c.targetCount);
      // Jumping a Saga's lore count by hand can cross several chapter
      // thresholds at once ΓÇö record each one it fires on the way up.
      const { triggeredChapters, crossed } = manualSagaChapters(c, to);
      if (to !== c.count) {
        log = appendLog(log, {
          turn: prev.game.turn,
          title: 'Manual edit',
          detail: `${c.name} set to ${to} (was ${c.count})${chapterNote(crossed)}`,
        });
      }
      // A manual edit restoring counters means it no longer holds that a
      // fade-counter removal failed ΓÇö but reaching 0 by hand isn't the
      // rule's actual upkeep trigger, so this never *sets* the flag, only
      // clears it (see hasHitTarget in utils/counters.ts).
      const fadeExhausted = c.mechanic === 'fading' && to > 0 ? false : c.fadeExhausted;
      return { ...c, count: to, triggeredChapters, fadeExhausted };
    });
    return { ...prev, game: { ...prev.game, cards, log } };
  });
}, []);

