display.text:
/** Appends a log entry, dropping the oldest once the cap is hit. */
function appendLog(log: LogEntry[], entry: Omit<LogEntry, 'id' | 'timestamp'>): LogEntry[] {
  const next = [...log, { ...entry, id: makeId(), timestamp: Date.now() }];
  return next.length > MAX_LOG_ENTRIES ? next.slice(next.length - MAX_LOG_ENTRIES) : next;
}

/**
 * The chapter(s) a manual count edit newly crosses on a Saga, plus its
 * updated triggeredChapters. Next Turn adds one lore counter at a time, but
 * setCount/adjustCount can jump the lore count by more than one ΓÇö every
 * threshold passed on the way *up* fires, exactly as it would over that many
 * turns (newlyTriggeredChapters fires forward only, so an edit that moves the
 * count back down refires nothing and un-triggers nothing, and a chapter
 * already in triggeredChapters never refires). Non-Saga cards are returned
 * untouched.
 */
function manualSagaChapters(
  c: TrackedCard,
  to: number,
): { triggeredChapters: number[] | undefined; crossed: { number: number; text: string }[] } {
  if (c.mechanic !== 'saga') return { triggeredChapters: c.triggeredChapters, crossed: [] };
  const crossed = newlyTriggeredChapters(c.chapters ?? [], c.count, to, c.triggeredChapters ?? []);
  if (crossed.length === 0) return { triggeredChapters: c.triggeredChapters, crossed };
  return {
    triggeredChapters: [...(c.triggeredChapters ?? []), ...crossed.map((t) => t.number)],
    crossed,
  };
}

/** Log suffix naming any chapter abilities a manual edit just fired (empty when none did). */
function chapterNote(crossed: { number: number; text: string }[]): string {
  if (crossed.length === 0) return '';
  const romans = crossed.map((ch) => chapterRoman(ch.number)).join(', ');
  return ` ΓÇö chapter${crossed.length === 1 ? '' : 's'} ${romans} triggered`;
}

