describe('useGameState ΓÇö manual Saga chapter triggers', () => {
  function addSaga(startingCount = 0) {
    return addInput({
      mechanic: 'saga',
      direction: 'increment',
      startingCount,
      targetCount: 3,
      chapters: ['Chapter I effect', 'Chapter II effect', 'Chapter III effect'],
    });
  }

  it('setCount jumping across multiple chapter thresholds records all of them', () => {
    const { result } = renderHook(() => useGameState());
    act(() => result.current.addCard(addSaga(0)));
    const id = result.current.state.cards[0]!.instanceId;
    act(() => result.current.setCount(id, 2));
    expect(result.current.state.cards[0]!.count).toBe(2);
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1, 2]);
  });

  it('setCount logs the chapters a manual jump crossed', () => {
    const { result } = renderHook(() => useGameState());
    act(() => result.current.addCard(addSaga(0)));
    const id = result.current.state.cards[0]!.instanceId;
    act(() => result.current.setCount(id, 2));
    const [entry] = result.current.state.log.slice(-1);
    expect(entry!.title).toBe('Manual edit');
    expect(entry!.detail).toContain('chapters I, II triggered');
  });

  it('adjustCount stepping up across a threshold records that chapter', () => {
    const { result } = renderHook(() => useGameState());
    act(() => result.current.addCard(addSaga(0)));
    const id = result.current.state.cards[0]!.instanceId;
    act(() => result.current.adjustCount(id, 1));
    expect(result.current.state.cards[0]!.count).toBe(1);
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1]);
  });

  it('moving the count back down does not un-trigger a recorded chapter', () => {
    const { result } = renderHook(() => useGameState());
    act(() => result.current.addCard(addSaga(0)));
    const id = result.current.state.cards[0]!.instanceId;
    act(() => result.current.setCount(id, 2));
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1, 2]);
    act(() => result.current.adjustCount(id, -1));
    expect(result.current.state.cards[0]!.count).toBe(1);
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1, 2]);
  });

  it('does not re-trigger a chapter already recorded when the count climbs back over it', () => {
    const { result } = renderHook(() => useGameState());
    act(() => result.current.addCard(addSaga(0)));
    const id = result.current.state.cards[0]!.instanceId;
    act(() => result.current.setCount(id, 2)); // fires I, II
    act(() => result.current.setCount(id, 1)); // dip back down
    act(() => result.current.setCount(id, 2)); // climb again ΓÇö nothing new fires
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1, 2]);
  });
});

