  });
}
// See setCount above: restoring counters by hand clears the failed-
// removal flag, but reaching 0 this way never sets it.
const fadeExhausted = c.mechanic === 'fading' && to > 0 ? false : c.fadeExhausted;
return { ...c, count: to, fadeExhausted };

input.oldString:
const to = clampCount(c.count + delta, c.direction, c.targetCount);
// Stepping a Saga up across a chapter threshold fires it; stepping it
// back down fires nothing and un-triggers nothing already recorded.
const { triggeredChapters, crossed } = manualSagaChapters(c, to);
if (to !== c.count) {
  log = appendLog(log, {
    turn: prev.game.turn,
    title: 'Manual adjustment',
    detail: `${c.name} ${to > c.count ? '+1' : 'ΓêÆ1'} ΓåÆ ${to}${chapterNote(crossed)}`,
  });
}
// See setCount above: restoring counters by hand clears the failed-
// removal flag, but reaching 0 this way never sets it.
const fadeExhausted = c.mechanic === 'fading' && to > 0 ? false : c.fadeExhausted;
return { ...c, count: to, triggeredChapters, fadeExhausted };

